import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    category_map = {
        "Furnture": "Furniture",
        "Accesories": "Accessories",
        " Furniture": "Furniture",
        " Office Supplies": "Office Supplies",
        "Furniture ": "Furniture"
    }
    df["Category"] = df["Category"].astype(str).str.strip().replace(category_map)
    if "Revenue" in df.columns and "Quantity" in df.columns and "Price" in df.columns:
        df["Revenue"] = df["Quantity"] * df["Price"]
    return df

def answer(df):
    counts = df.groupby("Category")["Order_ID"].nunique()
    return {str(k): int(v) for k, v in counts.items() if pd.notna(k)}
